// n8n Function node (mode: Run Once for All Items)
// Adds storage for previous postback before the latest. Minimal edits for compatibility.

const items = $input.all();
const body = items[0]?.json?.body;
const entry = body?.entry?.[0]?.messaging?.[0];
const text = entry?.message?.text;
const senderId = entry?.sender?.id;
const postback = entry?.postback?.payload;

// Use n8n's staticData to persist across executions (per workflow run)
const staticData = $getWorkflowStaticData('global');
const senderKey = `user_${senderId}`;

// Get previous postback for this sender (if any)
const previous = staticData[senderKey]?.previousPostback || null;
const latest = staticData[senderKey]?.latestPostback || null;

if (
  body?.object === 'page' &&
  senderId
) {
  // Handle "Get Started" text
  if (text && text.trim().toLowerCase() === 'get started') {
    return [{
      json: {
        type: 'text',
        text: 'get started',
        senderId,
        previousPostback: previous,
        latestPostback: latest
      }
    }];
  }
  // Handle postback button
  if (postback) {
    // Update staticData: shift latest to previous, store new postback as latest
    staticData[senderKey] = {
      previousPostback: latest,
      latestPostback: postback
    };
    return [{
      json: {
        type: 'postback',
        postback,
        senderId,
        previousPostback: latest,
        latestPostback: postback
      }
    }];
  }
  // Ignore other messages (optional)
  return [];
} else {
  return [{
    json: { error: 'Invalid payload or missing sender' }
  }];
}

