// Suppose the incoming postback is in item.json.postback
const postback = $input.first().json.postback; // e.g. "ADD_ON|AD-BOB|ADD_CF-CAR"

const [ , addOn, baseDrinkRaw ] = postback.split('|');

// Remove "ADD_" prefix from baseDrink if it exists
const baseDrink = baseDrinkRaw.startsWith('ADD_') ? baseDrinkRaw.slice(4) : baseDrinkRaw;

// Set the extracted values as new fields for use in later nodes
return {
  json: {
    addOn,      // "AD-BOB"
    baseDrink   // "CF-CAR"
  }
};

// Check Ingredient Stock - Code Node
const drinkData = $('fetch baseDrink').first().json;
const extractedData = $('extract values').first().json;

// Safely get add-on data - handle when node returns nothing
let addOnData = null;
try {
  const addOnNode = $('fetch add-on').first();
  addOnData = addOnNode ? addOnNode.json : null;
} catch (error) {
  // Node didn't return any data
  addOnData = null;
}

// Check if drink exists
if (!drinkData || Object.keys(drinkData).length === 0) {
  return [{
    json: {
      success: false,
      message: `Sorry, the drink "${extractedData.baseDrink}" is not available in our menu.`,
      code: 'PRODUCT_NOT_FOUND',
      senderId: $('Listen').first().json.senderId
    }
  }];
}

// Handle add-on validation
let validatedAddOnData = null;

if (extractedData.addOn && extractedData.addOn !== 'NONE') {
  // User selected an add-on, validate it exists
  if (!addOnData || Object.keys(addOnData).length === 0) {
    return [{
      json: {
        success: false,
        message: `Sorry, the selected add-on "${extractedData.addOn}" is not available.`,
        code: 'ADDON_NOT_FOUND',
        senderId: $('Listen').first().json.senderId
      }
    }];
  }

  // Check add-on stock and availability
  if (addOnData.Quantity <= 0 || !addOnData.IsEnabled) {
    return [{
      json: {
        success: false,
        message: `Sorry, ${addOnData.Name} is currently out of stock. Please choose a different add-on.`,
        code: 'ADDON_OUT_OF_STOCK',
        senderId: $('Listen').first().json.senderId
      }
    }];
  }

  validatedAddOnData = addOnData;
} else {
  // No add-on selected (NONE or null/undefined) or fetch returned nothing
  validatedAddOnData = {
    AddOnID: 'NONE',
    Name: 'No Add-on',
    Price: 0,
    Quantity: Infinity,
    IsEnabled: true
  };
}

// Prepare data for ingredient checking
return [{
  json: {
    drinkData,
    addOnData: validatedAddOnData,
    extractedData,
    senderId: $('Listen').first().json.senderId,
    ingredients: drinkData.Ingredients || []
  }
}];

// Validate Stock Levels - Code Node

// Safely get all required data with proper validation
let allIngredientStocks = [];
try {
  const ingredientNodes = $('fetch ingredients stock').all();
  allIngredientStocks = ingredientNodes && ingredientNodes.length > 0 
    ? ingredientNodes.map(item => item.json) 
    : [];
} catch (error) {
  console.log('No ingredient stock data found');
  allIngredientStocks = [];
}

// Safely get drink data
let drinkData = null;
try {
  drinkData = $('fetch baseDrink').first().json;
} catch (error) {
  drinkData = null;
}

// Safely get add-on data
let addOnData = null;
try {
  const addOnNode = $('fetch add-on').first();
  addOnData = addOnNode ? addOnNode.json : null;
} catch (error) {
  addOnData = null;
}

// Safely get extracted data
let extractedData = null;
try {
  extractedData = $('extract values').first().json;
} catch (error) {
  extractedData = null;
}

// Safely get sender ID
let senderId = null;
try {
  senderId = $('Listen').first().json.senderId;
} catch (error) {
  senderId = 'unknown_user';
}

// Validate essential data exists
if (!drinkData || !extractedData) {
  return [{
    json: {
      success: false,
      message: 'Missing essential order data. Please try again.',
      code: 'MISSING_DATA',
      senderId
    }
  }];
}

// Handle add-on data - create default if none selected
if (!addOnData && (!extractedData.addOn || extractedData.addOn === 'NONE')) {
  addOnData = {
    AddOnID: 'NONE',
    Name: 'No Add-on',
    Price: 0,
    Quantity: Infinity,
    IsEnabled: true
  };
}

let requiredIngredients = drinkData.Ingredients || [];

// Ensure it's an array
if (!Array.isArray(requiredIngredients)) {
  requiredIngredients = requiredIngredients ? [requiredIngredients] : [];
}

console.log('Required Ingredients (IDs):', requiredIngredients);
console.log('Available Stock Data:', allIngredientStocks);

// Check if ingredient stock data is available
if (requiredIngredients.length > 0 && allIngredientStocks.length === 0) {
  return [{
    json: {
      success: false,
      message: 'Unable to check ingredient availability. Please try again later.',
      code: 'STOCK_DATA_UNAVAILABLE',
      senderId
    }
  }];
}

// Check if all required ingredients are available
const unavailableIngredients = [];

for (const requiredIngredientId of requiredIngredients) {
  if (!requiredIngredientId) continue;

  // Match by IngredientID field (not _id)
  const stock = allIngredientStocks.find(item => item.IngredientID === requiredIngredientId);

  console.log(`Looking for: ${requiredIngredientId}, Found:`, stock);

  if (!stock || stock.Quantity <= 0 || !stock.IsEnabled) {
    unavailableIngredients.push({
      ingredientId: requiredIngredientId,
      name: stock ? stock.Name : 'Unknown Ingredient',
      available: false,
      quantity: stock ? stock.Quantity : 0,
      enabled: stock ? stock.IsEnabled : false
    });
  }
}

// If any ingredients are unavailable, return error
if (unavailableIngredients.length > 0) {
  const unavailableNames = unavailableIngredients.map(item => item.name).join(', ');
  return [{
    json: {
      success: false,
      message: `Sorry, "${drinkData.Name}" is currently unavailable due to insufficient stock of: ${unavailableNames}`,
      code: 'INSUFFICIENT_INGREDIENTS',
      unavailableIngredients,
      senderId
    }
  }];
}

// All ingredients available - proceed to add to cart
const basePrice = drinkData.Price || 0;
const addOnPrice = addOnData ? (addOnData.Price || 0) : 0;
const totalPrice = basePrice + addOnPrice;

return [{
  json: {
    success: true,
    message: `Great! "${drinkData.Name}" with "${addOnData ? addOnData.Name : 'No Add-on'}" has been added to your cart.`,
    code: 'ORDER_ADDED_TO_CART',
    cartItem: {
      userId: senderId,
      productId: extractedData.baseDrink,
      productName: drinkData.Name,
      addOnId: extractedData.addOn || 'NONE',
      addOnName: addOnData ? addOnData.Name : 'No Add-on',
      quantity: 1,
      basePrice: basePrice,
      addOnPrice: addOnPrice,
      totalPrice: totalPrice,
      createdAt: new Date(),
      status: 'pending'
    },
    pricing: {
      basePrice,
      addOnPrice,
      totalPrice
    },
    senderId
  }
}];
